function SumOddElementsInEvenPositions(lst: seq<int>) : int
    reads lst
{
    var total := 0;
    var length := |lst|;
    var i := 0;

    while i < length
        decreases length - i
    {
        if (i % 2 == 0 && lst[i] % 2 != 0) {
            total := total + lst[i];
        }
        i := i + 1;
